"""Dispatch for native multi-axis rotary CuTe kernels."""

import torch

from kestrel_kernels.cubin_runtime import CubinFamily
from kestrel_kernels.fallback import ceil_div, is_cute_jit_enabled, warn_and_run_fallback
from kestrel_kernels.multiaxis_rotary.config import (
    MULTIAXIS_ROTARY_TEXT_VARIANTS,
    MULTIAXIS_ROTARY_SPATIAL_VARIANTS,
    spatial_launch_threads,
    text_heads_per_block,
    text_launch_threads,
)
from kestrel_kernels.multiaxis_rotary.fallback import (
    spatial_rope_apply_torch,
    text_mrope_apply_torch,
)

_family = CubinFamily("multiaxis_rotary")
_ENABLE_JIT = is_cute_jit_enabled()

_TEXT_VARIANTS = {params: key for key, params in MULTIAXIS_ROTARY_TEXT_VARIANTS.items()}
_SPATIAL_VARIANTS = {
    params: key for key, params in MULTIAXIS_ROTARY_SPATIAL_VARIANTS.items()
}


def _variant_threads(variant_key: str) -> int:
    text_params = MULTIAXIS_ROTARY_TEXT_VARIANTS.get(variant_key)
    if text_params is not None:
        num_heads, num_kv_heads, _, rotary_dim = text_params
        return text_launch_threads(num_heads, num_kv_heads, rotary_dim)

    spatial_params = MULTIAXIS_ROTARY_SPATIAL_VARIANTS.get(variant_key)
    if spatial_params is not None:
        num_heads, _, rotary_dim, _, _ = spatial_params
        return spatial_launch_threads(num_heads, rotary_dim)

    raise ValueError(f"unknown multi-axis rotary variant {variant_key!r}")


def _ensure_variant(variant_key: str, tensor: torch.Tensor) -> bool:
    device_index = int(tensor.device.index or 0)
    if (variant_key, device_index) in _family._handles:
        return True
    if _family.is_available(variant_key):
        return True
    if not _ENABLE_JIT:
        return False
    from scripts.precompile import cubin_bundles as _cubin_bundles

    _cubin_bundles.jit_compile_and_install(
        family=_family,
        variant_key=variant_key,
        compile_fn=_cubin_bundles._compile_multiaxis_rotary(variant_key),
        block_x=_variant_threads(variant_key),
        device_index=device_index,
    )
    return True


def text_mrope_apply(
    query: torch.Tensor,
    key: torch.Tensor,
    cos: torch.Tensor,
    sin: torch.Tensor,
) -> tuple[torch.Tensor, torch.Tensor]:
    """Apply Qwen text M-RoPE to query/key [B, H, S, D]."""

    shape_key = (
        int(query.shape[1]) if query.ndim == 4 else -1,
        int(key.shape[1]) if key.ndim == 4 else -1,
        int(query.shape[3]) if query.ndim == 4 else -1,
        int(cos.shape[2]) if cos.ndim == 3 else -1,
    )
    variant_key = _TEXT_VARIANTS.get(shape_key)
    supported = (
        variant_key is not None
        and query.is_cuda
        and key.is_cuda
        and cos.is_cuda
        and sin.is_cuda
        and query.dtype == torch.bfloat16
        and key.dtype == torch.bfloat16
        and cos.dtype == torch.bfloat16
        and sin.dtype == torch.bfloat16
        and query.ndim == 4
        and key.ndim == 4
        and cos.ndim == 3
        and sin.shape == cos.shape
        and key.shape[3] == query.shape[3]
        and query.shape[0] == key.shape[0] == cos.shape[0]
        and query.shape[2] == key.shape[2] == cos.shape[1]
        and query.stride(-1) == 1
        and key.stride(-1) == 1
        and cos.stride(-1) == 1
        and sin.stride(-1) == 1
        and _ensure_variant(variant_key, query)
    )
    if supported:
        batch = int(query.shape[0])
        seq_len = int(query.shape[2])
        num_heads = int(query.shape[1])
        num_kv_heads = int(key.shape[1])
        rotary_dim = int(cos.shape[2])
        heads_per_block = text_heads_per_block(num_heads, num_kv_heads, rotary_dim)
        head_groups = ceil_div(num_heads + num_kv_heads, heads_per_block)
        dispatch = _family.resolve_dispatch(
            query,
            variant_key=variant_key,
            grid_x=batch * seq_len,
            grid_y=head_groups,
        )
        dispatch(query, key, cos, sin)
        return query, key

    return warn_and_run_fallback(
        kernel_key="qwen_text_mrope_apply",
        message=(
            "kestrel-kernels: no native Qwen text M-RoPE variant for "
            f"query={tuple(query.shape)} dtype={query.dtype}; using PyTorch fallback."
        ),
        fallback=text_mrope_apply_torch,
        args=(query, key, cos, sin),
    )


def spatial_rope_apply(
    query: torch.Tensor,
    key: torch.Tensor,
    cos: torch.Tensor,
    sin: torch.Tensor,
    *,
    axis_blocks: int = 1,
) -> tuple[torch.Tensor, torch.Tensor]:
    """Apply block-wise spatial RoPE over arbitrary leading token dimensions."""

    shape_key = (
        int(query.shape[-2]) if query.ndim >= 3 else -1,
        int(query.shape[-1]) if query.ndim >= 3 else -1,
        int(cos.shape[-1]) if cos.ndim == query.ndim - 1 else -1,
        int(axis_blocks),
        str(cos.dtype).removeprefix("torch."),
    )
    variant_key = _SPATIAL_VARIANTS.get(shape_key)
    supported = (
        variant_key is not None
        and query.is_cuda
        and key.is_cuda
        and cos.is_cuda
        and sin.is_cuda
        and query.dtype == torch.bfloat16
        and key.dtype == torch.bfloat16
        and cos.dtype in (torch.bfloat16, torch.float32)
        and sin.dtype == cos.dtype
        and query.ndim >= 3
        and key.shape == query.shape
        and cos.ndim == query.ndim - 1
        and sin.shape == cos.shape
        and cos.shape[:-1] == query.shape[:-2]
        and cos.shape[-1] == query.shape[-1]
        and query.stride(-1) == 1
        and key.stride(-1) == 1
        and cos.stride(-1) == 1
        and sin.stride(-1) == 1
        and _ensure_variant(variant_key, query)
    )
    if supported:
        try:
            flat_query = query.view(-1, query.shape[-2], query.shape[-1])
            flat_key = key.view_as(flat_query)
            flat_cos = cos.view(-1, cos.shape[-1])
            flat_sin = sin.view_as(flat_cos)
        except RuntimeError:
            supported = False

    if supported:
        dispatch = _family.resolve_dispatch(
            flat_query,
            variant_key=variant_key,
            grid_x=int(flat_query.shape[0]),
        )
        dispatch(flat_query, flat_key, flat_cos, flat_sin)
        return query, key

    return warn_and_run_fallback(
        kernel_key="spatial_rope_apply",
        message=(
            "kestrel-kernels: no native spatial RoPE variant for "
            f"query={tuple(query.shape)} dtype={query.dtype}; using PyTorch fallback."
        ),
        fallback=spatial_rope_apply_torch,
        args=(query, key, cos, sin),
        kwargs={"axis_blocks": axis_blocks},
    )


__all__ = ["spatial_rope_apply", "text_mrope_apply"]
